using System.Text;
using UnityEngine;

public class LoadingPanelInspect
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();

        foreach (GameObject go in Object.FindObjectsOfType<GameObject>())
        {
            if (go.transform.parent != null)
                continue;

            sb.AppendLine("ROOT " + go.name + " scene=" + go.scene.name + " active=" + go.activeSelf);
            dump(go.transform, sb, "    ");
        }

        Debug.Log("[LoadingInspect]\n" + sb);
    }

    private static void dump(Transform t, StringBuilder sb, string indent)
    {
        foreach (Transform child in t)
        {
            sb.AppendLine(indent + child.name + " active=" + child.gameObject.activeSelf
                + " anchored=" + (child as RectTransform != null ? (child as RectTransform).anchoredPosition.ToString() : "-")
                + " size=" + (child as RectTransform != null ? (child as RectTransform).sizeDelta.ToString() : "-"));
            dump(child, sb, indent + "  ");
        }
    }
}
